package com.minecraft.core.member.list.bedwars.objects.enums;

import lombok.AllArgsConstructor;
import lombok.Getter;

import java.util.stream.Stream;

@Getter
@AllArgsConstructor
public enum BedSkin {

    RED("Vermelho", "", ""),
    BLUE("Azul", "", ""),
    YEL("Amarelo", "", ""),
    ORAN("Laranja", "", ""),
    PURP("Roxo", "", ""),
    CYAN("Ciano", "", ""),
    WHIT("Branco", "", ""),
    GRAY("Cinza", "", "");

    private final String name, value, signature;

    public static BedSkin of(String name) {
        return Stream.of(values())
                .filter(skin -> skin.name().equalsIgnoreCase(name) || skin.getName().equalsIgnoreCase(name))
                .findFirst()
                .orElse(null);
    }
}
